import random, sys, json

HDR = r'''
import re
def enc(o):
    if o is None: return "None"
    if isinstance(o, bool): return str(o)
    if isinstance(o, int): return str(o)
    if isinstance(o, str):
        r = []
        for ch in o:
            c = ord(ch)
            if 32 <= c < 127 and ch != "\\" and ch != "|":
                r.append(ch)
            else:
                r.append("\\x%04x" % c)
        return '"' + "".join(r) + '"'
    if isinstance(o, tuple):
        return "(" + ",".join([enc(x) for x in o]) + ")"
    if isinstance(o, list):
        return "[" + ",".join([enc(x) for x in o]) + "]"
    return "?" + str(o)

def run(op, pat, subj, fl):
    if op == "findall": return enc(re.findall(pat, subj, fl))
    if op == "split": return enc(re.split(pat, subj, 0, fl))
    if op == "sub": return enc(re.sub(pat, "-", subj, 0, fl))
    if op == "subx": return enc(re.sub(pat, "<\\g<0>>", subj, 0, fl))
    if op == "search":
        m = re.search(pat, subj, fl)
        return "None" if m is None else enc(list(m.span())) + enc(m.group(0))
    if op == "fullmatch":
        m = re.fullmatch(pat, subj, fl)
        return "None" if m is None else enc(m.group(0))
    if op == "finditer":
        return enc([m.group(0) for m in re.finditer(pat, subj, fl)])
    return "BADOP"

CASES = [
'''

TAIL = r'''
]
for i in range(len(CASES)):
    op, pat, subj, fl = CASES[i]
    try:
        r = run(op, pat, subj, fl)
    except NotImplementedError:
        r = "UNSUP"
    except Exception as e:
        r = "ERR:" + type(e).__name__
    print(str(i) + "|" + r)
'''

def pyrepr(s):
    # ASCII-only source literal so both interpreters parse it identically
    out = []
    for ch in s:
        c = ord(ch)
        if ch in ('"', "\\"):
            out.append("\\" + ch)
        elif 32 <= c < 127:
            out.append(ch)
        else:
            out.append("\\x%02x" % c if c < 256 else "\\u%04x" % c)
    return '"' + "".join(out) + '"'

def emit(cases, path):
    with open(path, "w") as f:
        f.write(HDR)
        for op, pat, subj, fl in cases:
            f.write("(%s, %s, %s, %d),\n" % (pyrepr(op), pyrepr(pat), pyrepr(subj), fl))
        f.write(TAIL)

