import re, random, sys, load_shim
s = load_shim.shim
ALPHA = list("ab1_.*+?{},[]()|^$-\\# \t\n:wdsWSAZ") + ["\\n","\\ ","\\#","\\\\","\\d","\\w","\\s","\\.","\\[","\\{","(?:", "\n", "  "]
SUBJ = ["", "a", "ab", "aab", "a b", "a#b", "a\nb", "{2,3}", "a{2,3}", "aaa bbb", "1a_ b2", "a,b", "-", "[]", "aaaa"]
rnd = random.Random(20260819)
bad = []
seen = set()
N = int(sys.argv[1])
tried = 0
for _ in range(N):
    p = "".join(rnd.choice(ALPHA) for _ in range(rnd.randint(1,7)))
    if p in seen: continue
    seen.add(p); tried += 1
    try:
        cp = re.compile(p, re.X); cperr = None
    except Exception as e:
        cp = None; cperr = type(e).__name__
    try:
        st = s._strip_verbose(p)
        sp = re.compile(st); sperr = None
    except Exception as e:
        sp = None; st = None; sperr = type(e).__name__
    if (cp is None) != (sp is None):
        bad.append(("compile", p, cperr, st, sperr)); continue
    if cp is None: continue
    for subj in SUBJ:
        try: a = cp.findall(subj)
        except Exception as e: a = "E"+type(e).__name__
        try: b = sp.findall(subj)
        except Exception as e: b = "E"+type(e).__name__
        if a != b:
            bad.append(("findall", p, st, subj, a, b)); break
print("tried", tried, "divergences", len(bad))
