b = [l.rstrip("\n") for l in open(sys.argv[2], encoding="latin-1")]
buckets = {"WRONG": [], "CRASH": [], "OVERACCEPT": []}
same = unsup = errboth = 0
for i, (x, y) in enumerate(zip(a, b)):
    xv = x.partition("|")[2]; yv = y.partition("|")[2]
