    if xe and not ye: buckets["OVERACCEPT"].append((i, CASES[i], xv, yv))
    elif ye and not xe: buckets["CRASH"].append((i, CASES[i], xv, yv))
    else: buckets["WRONG"].append((i, CASES[i], xv, yv))
